do $preflight$begin if(select md5(jsonb_agg(jsonb_build_array(role_id,resource_key,can_view,can_create,can_edit,can_delete)order by role_id,resource_key)::text)from public.role_access_matrix)is distinct from '4b802088a674bd134e5ab2571194b189'or(select md5(jsonb_agg(jsonb_build_array(role_id,role_name,is_system_role)order by role_id)::text)from public.roles)is distinct from '93a955b4209e1f962617e4f37df713f2'then raise exception 'Expanded role/matrix baseline changed; review before retiring legacy.';end if;end$preflight$;
